from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._store = OrderedDict()

    def _purge_expired(self, now: float) -> None:
        if not self._store:
            return

        expired_keys = [
            key
            for key, (_, expires_at) in self._store.items()
            if not now < expires_at
        ]
        for key in expired_keys:
            del self._store[key]

    def get(self, key, default=None):
        entry = self._store.get(key)
        if entry is None:
            return default

        value, expires_at = entry
        if not self.clock() < expires_at:
            return default

        self._store.move_to_end(key)
        return value

    def put(self, key, value) -> None:
        now = self.clock()
        self._purge_expired(now)

        expires_at = now + self.ttl

        # If it is not live at the moment it is written, it must behave as absent.
        if not now < expires_at:
            self._store.pop(key, None)
            return

        if key in self._store:
            self._store[key] = (value, expires_at)
            self._store.move_to_end(key)
        else:
            if len(self._store) >= self.capacity:
                self._store.popitem(last=False)
            self._store[key] = (value, expires_at)

    def __len__(self) -> int:
        if not self._store:
            return 0

        now = self.clock()
        return sum(1 for _, expires_at in self._store.values() if now < expires_at)
